#include <linux/if.h>
#include <linux/if_arp.h>
#include <linux/errno.h>
#include <linux/hdlc.h>
#include <linux/netdevice.h>
#include <linux/string.h>
#include <linux/uaccess.h>

int wan_ioctl(struct net_device *dev, struct ifreq *ifr, int cmd)
{
    struct hdlc_device *hdlc = dev_to_hdlc(dev);
    struct sync_serial_settings __user *user_set;
    struct sync_serial_settings set;
    int ret;

    if (cmd != SIOCWANDEV)
        return hdlc_ioctl(dev, ifr, cmd);

    switch (ifr->ifr_settings.type) {
    case IF_GET_IFACE:
        if (ifr->ifr_settings.size < sizeof(set)) {
            ifr->ifr_settings.size = sizeof(set);
            return -ENOBUFS;
        }

        memset(&set, 0, sizeof(set));
        set.clock_rate = hdlc->clock_rate;
        set.flags = hdlc->flags;
        set.line = hdlc->line;
        set.loopback = hdlc->loopback;

        if (copy_to_user(ifr->ifr_settings.ifsu_sync, &set, sizeof(set)))
            return -EFAULT;
        return 0;

    case IF_IFACE_SYNC_SERIAL:
        if (!capable(CAP_NET_ADMIN))
            return -EPERM;

        if (!netif_running(dev))
            return -EBUSY;

        if (ifr->ifr_settings.size < sizeof(set))
            return -EINVAL;

        user_set = ifr->ifr_settings.ifsu_sync;
        if (copy_from_user(&set, user_set, sizeof(set)))
            return -EFAULT;

        if (set.flags & ~HDLC_FLAG_MASK)
            return -EINVAL;

        hdlc->clock_rate = set.clock_rate;
        hdlc->flags = set.flags;
        hdlc->line = set.line;
        hdlc->loopback = set.loopback;
        return 0;

    default:
        return hdlc_ioctl(dev, ifr, cmd);
    }
}

int wan_ioctl(struct net_device *dev, struct ifreq *ifr, int cmd)
{
    struct sync_serial_settings settings;
    int err = 0;

    if (cmd != SIOCWANDEV)
        return hdlc_ioctl(dev, ifr, cmd);

    switch (((struct ifwanreq *)ifr)->ifr_type) {
    case IF_GET_IFACE:
    {
        size_t size;

        if (copy_from_user(&size, ifr->ifr_ifru.ifru_data, sizeof(size_t)))
            return -EFAULT;

        if (size < sizeof(struct sync_serial_settings)) {
            if (copy_to_user(ifr->ifr_ifru.ifru_data, &size, sizeof(size_t)))
                return -EFAULT;
            return -ENOBUFS;
        }

        memset(&settings, 0, sizeof(settings));
        settings.clock_type = dev->clock_type;
        settings.flags = dev->flags;

        if (copy_to_user(ifr->ifr_ifru.ifru_data, &settings, sizeof(settings)))
            return -EFAULT;
        break;
    }

    case IF_IFACE_SYNC_SERIAL:
    {
        if (!capable(CAP_NET_ADMIN))
            return -EPERM;

        if (dev->flags & IFF_UP)
            return -EBUSY;

        if (copy_from_user(&settings, ifr->ifr_ifru.ifru_data, sizeof(settings)))
            return -EFAULT;

        if (settings.clock_type > CLOCK_EXT) {
            err = -EINVAL;
            break;
        }

        dev->clock_type = settings.clock_type;
        dev->flags = settings.flags;
        break;
    }

    default:
        return hdlc_ioctl(dev, ifr, cmd);
    }

    return err;
}

#include <linux/netdevice.h>
#include <linux/if.h>
#include <linux/errno.h>
#include <linux/slab.h>
#include <linux/uaccess.h>
#include <linux/capability.h>
