int wan_ioctl(struct net_device *dev, struct ifreq *ifr, int cmd)
{
    struct sync_serial_settings __user *user_settings;
    struct sync_serial_settings settings;
    int ret = 0;

    if (cmd != SIOCWANDEV)
        return hdlc_ioctl(dev, ifr, cmd);

    switch (((struct wan_data *)dev->priv)->cfg.mode) {
    case IF_GET_IFACE:
        if (copy_from_user(&settings, ifr->ifr_ifsu.ifsu_data, sizeof(settings)))
            return -EFAULT;

        if (settings.size < sizeof(struct sync_serial_settings)) {
            settings.size = sizeof(struct sync_serial_settings);
            if (copy_to_user(ifr->ifr_ifsu.ifsu_data, &settings, sizeof(settings)))
                return -EFAULT;
            return -ENOBUFS;
        }

        settings = ((struct wan_data *)dev->priv)->cfg;
        if (copy_to_user(ifr->ifr_ifsu.ifsu_data, &settings, sizeof(settings)))
            return -EFAULT;
        return 0;

    case IF_IFACE_SYNC_SERIAL:
        if (!capable(CAP_NET_ADMIN))
            return -EPERM;

        if (dev->flags & IFF_RUNNING)
            return -EBUSY;

        if (copy_from_user(&settings, ifr->ifr_ifsu.ifsu_data, sizeof(settings)))
            return -EFAULT;

        if (settings.clocking != HDLC_CLK_INT &&
            settings.clocking != HDLC_CLK_EXT) {
            return -EINVAL;
        }

        ((struct wan_data *)dev->priv)->cfg = settings;
        return 0;

    default:
        return hdlc_ioctl(dev, ifr, cmd);
    }
}

int wan_ioctl(struct net_device *dev, struct ifreq *ifr, int cmd)
{
    int ret;
    struct sync_serial_settings settings;

    if (cmd != SIOCWANDEV)
        return hdlc_ioctl(dev, ifr, cmd);

    switch (((struct if_settings *)ifr->ifr_ifru.ifru_data)->type) {
    case IF_GET_IFACE:
        if (((struct if_settings *)ifr->ifr_ifru.ifru_data)->size <
            sizeof(struct sync_serial_settings)) {
            ((struct if_settings *)ifr->ifr_ifru.ifru_data)->size =
                sizeof(struct sync_serial_settings);
            return -ENOBUFS;
        }

        memset(&settings, 0, sizeof(settings));
        settings.clock_rate = dev->base_addr;
        settings.clock_source = dev->irq;
        settings.loopback = dev->flags & IFF_LOOPBACK;

        if (copy_to_user(ifr->ifr_ifru.ifru_data, &settings, sizeof(settings)))
            return -EFAULT;
        break;

    case IF_IFACE_SYNC_SERIAL:
        if (!capable(CAP_NET_ADMIN))
            return -EPERM;

        if (dev->flags & IFF_UP)
            return -EBUSY;

        if (copy_from_user(&settings, ifr->ifr_ifru.ifru_data, sizeof(settings)))
            return -EFAULT;

        if (settings.clock_rate > MAX_CLOCK_RATE || settings.clock_rate < MIN_CLOCK_RATE)
            return -EINVAL;

        dev->base_addr = settings.clock_rate;
        dev->irq = settings.clock_source;
        dev->flags = (dev->flags & ~IFF_LOOPBACK) | (settings.loopback ? IFF_LOOPBACK : 0);
        break;

    default:
        return hdlc_ioctl(dev, ifr, cmd);
    }

    return 0;
}

#include <linux/if.h>
#include <linux/if_wan.h>
#include <linux/hdlc.h>
#include <linux/uaccess.h>
#include <linux/errno.h>
#include <linux/capability.h>

int wan_ioctl(struct net_device *dev, struct ifreq *ifr, int cmd)
{
    struct wan_dev *wan = netdev_priv(dev);
    struct wan_sync_serial_settings *set;

    if (cmd != SIOCWANDEV)
        return hdlc_ioctl(dev, ifr, cmd);

    switch (cmd) {
    case IF_GET_IFACE:
        if (copy_from_user(&set, ifr->ifr_ifsu.ifsu_data, sizeof(set)))
            return -EFAULT;

        if (set->size < sizeof(*set)) {
            set->size = sizeof(*set);
            return -ENOBUFS;
        }

        set->clock_tx = wan->clock_tx;
        set->clock_rx = wan->clock_rx;
        set->clock_type = wan->clock_type;
        set->tx_speed = wan->tx_speed;
        set->rx_speed = wan->rx_speed;

        if (copy_to_user(ifr->ifr_ifsu.ifsu_data, &set, sizeof(set)))
            return -EFAULT;

        return 0;

    case IF_IFACE_SYNC_SERIAL:
        if (!capable(CAP_NET_ADMIN))
            return -EPERM;

        if (dev->flags & IFF_UP)
            return -EBUSY;

        if (copy_from_user(&set, ifr->ifr_ifsu.ifsu_data, sizeof(set)))
            return -EFAULT;

        if (set.size < sizeof(*set))
            return -EINVAL;

        if (set.clock_tx != WAN_CLOCK_INT && set.clock_tx != WAN_CLOCK_EXT)
            return -EINVAL;

        if (set.clock_rx != WAN_CLOCK_INT && set.clock_rx != WAN_CLOCK_EXT)
            return -EINVAL;

        if (set.clock_type != WAN_CTYPE_DTE && set.clock_type != WAN_CTYPE_DCE)
            return -EINVAL;

        wan->clock_tx = set.clock_tx;
        wan->clock_rx = set.clock_rx;
        wan->clock_type = set.clock_type;
        wan->tx_speed = set.tx_speed;
        wan->rx_speed = set.rx_speed;

        return 0;

    default:
        return hdlc_ioctl(dev, ifr, cmd);
    }
}
